"""Interval merging."""


def merge_intervals(intervals):
    """Merge overlapping or touching integer intervals.

    intervals: iterable of [start, end] pairs (integers).
    Returns new sorted list of merged [start, end] pairs.
    Input is never mutated. Reversed pair (start > end) raises ValueError.
    """
    pairs = []
    for pair in intervals:
        try:
            start, end = pair
        except (TypeError, ValueError):
            raise ValueError("each interval must be a pair of two values") from None
        if isinstance(start, bool) or isinstance(end, bool) or \
                not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("interval endpoints must be integers")
        if start > end:
            raise ValueError("reversed interval: start %r > end %r" % (start, end))
        pairs.append((start, end))

    if not pairs:
        return []

    pairs.sort()
    merged = [list(pairs[0])]
    for start, end in pairs[1:]:
        last = merged[-1]
        if start <= last[1] + 1:  # overlap or touching (endpoints adjacent)
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

