"""Exact decimal arithmetic over a sequence of ledger rows."""

from decimal import Decimal, InvalidOperation

__all__ = ["total"]


def _to_decimal(row):
    """Convert one row to a finite Decimal, or None for blank rows."""
    if isinstance(row, str):
        text = row.strip()
        if not text:
            return None
        try:
            value = Decimal(text)
        except (InvalidOperation, ValueError) as exc:
            raise ValueError("malformed numeric value: {!r}".format(row)) from exc
    elif isinstance(row, bool):
        raise ValueError("malformed numeric value: {!r}".format(row))
    elif isinstance(row, (Decimal, int)):
        value = Decimal(row)
    elif isinstance(row, float):
        value = Decimal(repr(row))
    else:
        raise ValueError("malformed numeric value: {!r}".format(row))

    if not value.is_finite():
        raise ValueError("malformed numeric value: {!r}".format(row))
    return value


def total(rows):
    """Return the exact sum of `rows` as a Decimal.

    Signed amounts ("+1.50", "-2.00") are accepted, blank/whitespace-only
    rows are ignored, and malformed numeric values raise ValueError.
    """
    result = Decimal("0")
    for row in rows:
        value = _to_decimal(row)
        if value is not None:
            result += value
    return result

