"""Ledger totals with exact decimal arithmetic."""

from decimal import Decimal, InvalidOperation, localcontext

__all__ = ["total"]


def _parse(item):
    """Return a finite Decimal for one row, ignoring blanks; else ValueError."""
    if item is None:
        return None
    if isinstance(item, str):
        text = item.strip()
        if not text:  # blank / whitespace-only row -> ignore
            return None
        raw = text
    elif isinstance(item, Decimal):
        raw = item
    elif isinstance(item, bool):
        raise ValueError("malformed amount: %r" % (item,))
    elif isinstance(item, int):
        raw = Decimal(item)
    elif isinstance(item, float):
        # repr() gives the shortest decimal that round-trips, so there is no
        # binary expansion drift (0.1 + 0.2 == Decimal("0.3"))
        raw = repr(item)
    else:
        raise ValueError("unsupported amount type: %r" % (item,))

    try:
        value = raw if isinstance(raw, Decimal) else Decimal(raw)
    except (InvalidOperation, ValueError, ArithmeticError) as exc:
        raise ValueError("malformed amount: %r" % (item,)) from exc

    if not value.is_finite():
        raise ValueError("malformed amount: %r" % (item,))
    return value


def total(rows):
    """Sum monetary amounts exactly with Decimal.

    rows: iterable of amount strings (also Decimal/int/float).
    - Blank and whitespace-only entries are ignored.
    - Signed amounts ("-12.50", "+3", "1e3") are accepted.
    - A malformed numeric value raises ValueError.
    """
    if rows is None:
        raise ValueError("rows must be an iterable of amounts")

    values = []
    for item in rows:
        value = _parse(item)
        if value is not None:
            values.append(value)

    if not values:
        return Decimal("0")

    # Size the arithmetic context to the inputs so addition is exact: the
    # default prec=28 would silently round a long sum.
    highest = max(v.adjusted() for v in values)
    lowest = min(v.adjusted() for v in values)
    digits = max(len(v.as_tuple().digits) for v in values)
    prec = highest - lowest + digits + 2
    if prec < 1:
        prec = 1

    with localcontext() as ctx:
        ctx.prec = prec
        if highest + 1 > ctx.Emax:
            ctx.Emax = highest + 1
        if lowest - 1 < ctx.Emin:
            ctx.Emin = lowest - 1
        result = sum(values, Decimal("0"))
    return result

