"""Merge integer intervals.

merge_intervals(intervals) takes an iterable of [start, end] pairs and returns a
new list of merged intervals. Overlapping intervals and intervals that merely
touch (end + 1 == next start) are merged, the result is sorted by start, the
input is never mutated, and reversed pairs (start > end) raise ValueError.
"""

from __future__ import annotations

from typing import Iterable, List, Sequence

Interval = List[int]


def _normalize(intervals: Iterable[Sequence[int]]) -> List[Interval]:
    """Validate the input and return a fresh list of independent copies."""
    if isinstance(intervals, (str, bytes)):
        raise ValueError(f"intervals must be a sequence of pairs, got {type(intervals).__name__}")

    try:
        items = list(intervals)
    except TypeError:
        raise ValueError(f"intervals must be iterable, got {type(intervals).__name__}") from None

    normalized: List[Interval] = []
    for index, item in enumerate(items):
        if isinstance(item, (str, bytes)):
            raise ValueError(f"interval at index {index} is not a pair: {item!r}")
        try:
            pair = list(item)
        except TypeError:
            raise ValueError(f"interval at index {index} is not a pair: {item!r}") from None
        if len(pair) != 2:
            raise ValueError(f"interval at index {index} must have exactly 2 values: {item!r}")
        start, end = pair
        for value in (start, end):
            if isinstance(value, bool) or not isinstance(value, int):
                raise ValueError(f"interval at index {index} has non-integer bound: {value!r}")
        if start > end:
            raise ValueError(f"reversed interval at index {index}: [{start}, {end}]")
        normalized.append([start, end])
    return normalized


def merge_intervals(intervals: Iterable[Sequence[int]]) -> List[Interval]:
    """Merge overlapping and touching integer intervals.

    Args:
        intervals: iterable of [start, end] pairs with start <= end.

    Returns:
        Sorted list of merged [start, end] lists.

    Raises:
        ValueError: if an interval is malformed or reversed (start > end).
    """
    items = _normalize(intervals)
    if not items:
        return []

    items.sort(key=lambda pair: (pair[0], pair[1]))

    merged: List[Interval] = [items[0]]
    for start, end in items[1:]:
        last = merged[-1]
        if start <= last[1] + 1:  # overlap or touching endpoint
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged


if __name__ == "__main__":
    print(merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]))

