def _to_decimal(row):
    """Convert one ledger row into an exact Decimal amount.

    Blank rows (empty or whitespace-only strings) are skipped by the caller.
    Anything that is not a finite numeric amount raises ValueError.
    """
    if isinstance(row, bool):
        raise ValueError("malformed numeric value: %r" % (row,))
    if isinstance(row, int):
        return Decimal(row)
    if isinstance(row, float):
        # repr keeps the shortest round-trip form; never raises.
        return Decimal(repr(row))
    if isinstance(row, Decimal):
