            text = row.decode("utf-8").strip()
        except UnicodeDecodeError as exc:
            raise ValueError("malformed numeric value: %r" % (row,)) from exc
        if not text:
            return None
        try:
            value = Decimal(text)
        except (InvalidOperation, ValueError) as exc:
            raise ValueError("malformed numeric value: %r" % (row,)) from exc
    else:
        raise ValueError("malformed numeric value: %r" % (row,))

    if not value.is_finite():
        raise ValueError("malformed numeric value: %r" % (row,))
    return value


