import re
from decimal import Decimal, InvalidOperation

__all__ = ["total"]

# Strict plain-decimal form: no underscores, no words like nan/inf, no hex.
_NUMBER_RE = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?\Z")


def _to_decimal(value):
    """Convert one row value to a finite Decimal.

    Raises ValueError for anything that is not a well-formed, finite number.
    """
    if isinstance(value, bool):
        raise ValueError("malformed numeric value: %r" % (value,))

    if isinstance(value, Decimal):
        result = value
    elif isinstance(value, int):
        result = Decimal(value)
    elif isinstance(value, float):
        if value != value or value in (float("inf"), float("-inf")):
            raise ValueError("malformed numeric value: %r" % (value,))
        result = Decimal(str(value))
    elif isinstance(value, str):
        result = _parse_str(value)
    else:
        raise ValueError("malformed numeric value: %r" % (value,))

    if not result.is_finite():
        raise ValueError("malformed numeric value: %r" % (value,))
    return result


def _parse_str(text):
    stripped = text.strip()
    if not stripped or not _NUMBER_RE.match(stripped):
        raise ValueError("malformed numeric value: %r" % (text,))
    try:
        return Decimal(stripped)
    except InvalidOperation as exc:
        raise ValueError("malformed numeric value: %r" % (text,)) from exc


def total(rows):
    """Sum signed amounts exactly.

    - amounts may be ints, Decimals, floats or strings, positive or negative
    - blank/whitespace-only lines are ignored
    - malformed numeric values raise ValueError
    - the running total is exact (Decimal), no float drift
    """
    if rows is None:
        raise ValueError("rows must be an iterable of amounts, got None")

    running = Decimal(0)
    for row in rows:
        if isinstance(row, str) and not row.strip():
            continue
        running += _to_decimal(row)
    return running

